import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { buildProgram } from '../../index';

/**
 * README.md and SKILL.md are generated by app-agent-codegen, whose prose sections are written
 * by hand: the generator has no way to know which flags the runtime actually declares. So a flag
 * renamed here (`--scaffold-only`, `--no-run`) leaves the shipped docs telling people to type
 * something that no longer exists, and nothing in either repository notices.
 *
 * These read the committed docs and check them against the real command, which is the one place
 * the two can be compared. A rename now fails here, and the fix is to rename it in the generator
 * too - exactly the gate that was missing.
 */
const repoRoot = join(__dirname, '..', '..', '..');
const read = (file: string): string => readFileSync(join(repoRoot, file), 'utf8');

/** The flags the command really has, as commander knows them. */
const declaredFlags = (): string[] => {
  const command = buildProgram().commands.find((child) => child.name() === 'get-started');
  if (!command) throw new Error('no get-started command is registered');
  return command.options.map((option) => option.long).filter((long): long is string => Boolean(long));
};

/** Every `--flag` a documentation section mentions. */
const mentionedFlags = (section: string): string[] => [
  ...new Set([...section.matchAll(/--[a-z][a-z-]*/g)].map((match) => match[0])),
];

const sectionOf = (markdown: string, heading: string, until: string): string => {
  const start = markdown.indexOf(heading);
  if (start < 0) throw new Error(`no "${heading}" section; the generator stopped emitting it`);
  const end = markdown.indexOf(until, start + heading.length);
  return markdown.slice(start, end < 0 ? undefined : end);
};

describe('the shipped docs for get-started', () => {
  it('names only flags the command actually has', () => {
    const documented = mentionedFlags(sectionOf(read('README.md'), '## Get started', '## Usage'));
    const real = declaredFlags();

    expect(documented.length).toBeGreaterThan(0);
    for (const flag of documented) expect(real).toContain(flag);
  });

  it('names only flags the command actually has, in SKILL.md too', () => {
    const documented = mentionedFlags(sectionOf(read('SKILL.md'), '## Get started', '## Shape of a command'));
    const real = declaredFlags();

    expect(documented.length).toBeGreaterThan(0);
    for (const flag of documented) expect(real).toContain(flag);
  });

  it('documents the flag that makes it usable without a terminal', () => {
    // The one flag a script or a CI job needs. Losing it from the docs is losing the only
    // answer to "this prompts, so I cannot use it".
    expect(read('README.md')).toContain('--scaffold-only');
    expect(read('SKILL.md')).toContain('--scaffold-only');
  });
});
